import { useLayoutEffect, useMemo, useRef, useState } from "react";
import { AbsoluteFill, useCurrentFrame, useDelayRender } from "remotion";
import { alpha, exitOut, fill, FONTS, loadMotionFonts, ramp, unit } from "../lib";
import type { MotionBaseProps } from "../types";

type Props = MotionBaseProps & {
  lines: string[];
  font: string;
  weight: string;
  size: number;
  color: string;
  accent: string;
  background: string;
  dot: number;
  build: number;
};

/**
 * "Generated by *multi word* agents" → plain and highlighted runs, spaces kept. A starred run may span
 * words; every star is dropped, so the type and the traced dots spell the same text.
 */
function highlightRuns(line: string) {
  return line
    .split(/(\*[^*]+\*)/)
    .filter(Boolean)
    .map((part) => ({ text: part.replace(/\*/g, ""), highlighted: /^\*[^*]+\*$/.test(part) }))
    .filter((run) => run.text);
}

/** Dots (x, y in grid cells, coverage 0–1) where the headline has ink. */
interface DotSet {
  cols: number;
  rows: number;
  dots: Float32Array;
}

/**
 * A headline that an agent seems to generate: a scan line traces its letters in dots, the dots swell
 * into the glyphs and the real type resolves out of a blur.
 */
export function DotTraceTitle(props: Props) {
  const frame = useCurrentFrame();
  const { width, height, fps, durationInFrames: d } = props;
  const canvas = useRef<HTMLCanvasElement>(null);
  const { delayRender, continueRender } = useDelayRender();
  const u = unit(width, height);
  const fontSize = Math.round((props.size / 100) * Math.min(width, height) * 0.9);
  const family = FONTS[props.font] ?? FONTS.display;
  const font = `${props.weight} ${fontSize}px ${family}`;
  // Spaces collapsed like the DOM does, so the canvas traces exactly the type it resolves into.
  const lines = props.lines
    .map((line) => line.replace(/\s+/g, " ").trim())
    .filter(Boolean)
    .slice(0, 3);
  const text = lines.map((line) => line.replace(/\*/g, ""));
  const textKey = text.join("\n");
  const lineHeight = fontSize * 1.02;
  const top = height / 2 - (lines.length * lineHeight) / 2;
  const pitch = Math.max(4, props.dot * u);
  const buildFrames = Math.max(12, Math.round(props.build * fps));
  const trace = ramp(frame, 0, buildFrames * 0.6);
  const resolve = ramp(frame, buildFrames * 0.45, buildFrames * 0.55);
  const out = exitOut(frame, d, 12);

  // The dots are traced from the real font, never a fallback: hold the render until this exact face is
  // in (from the first commit, in a layout effect), and release it once a frame is drawn with it, or
  // in cleanup (unmount, StrictMode's second mount, a new font).
  const [fontReady, setFontReady] = useState<string | null>(null);
  const releaseFont = useRef<(() => void) | null>(null);
  useLayoutEffect(() => {
    let alive = true;
    let released = false;
    const handle = delayRender(`Loading ${font} for DotTraceTitle`);
    const release = () => {
      if (released) return;
      released = true;
      continueRender(handle);
    };
    releaseFont.current = release;
    // loadMotionFonts resolves even when the network fails (the type falls back), so this always ends.
    loadMotionFonts()
      .then(() => document.fonts.load(font, textKey || "A"))
      .catch(() => undefined)
      .then(() => {
        if (alive) setFontReady(font);
      });
    return () => {
      alive = false;
      if (releaseFont.current === release) releaseFont.current = null;
      release();
    };
  }, [font, textKey, delayRender, continueRender]);
  const ready = fontReady === font;

  // Sample the headline's own pixels on a dot grid offscreen, once per text, font and grid.
  const dotSet = useMemo<DotSet | null>(() => {
    if (!ready || typeof document === "undefined") return null;
    const off = document.createElement("canvas");
    off.width = Math.ceil(width / pitch);
    off.height = Math.ceil(height / pitch);
    const o = off.getContext("2d");
    if (!o) return null;
    o.scale(1 / pitch, 1 / pitch);
    o.fillStyle = "#fff";
    o.textAlign = "center";
    o.textBaseline = "middle";
    o.font = font;
    textKey.split("\n").forEach((line, i) => o.fillText(line, width / 2, top + lineHeight * (i + 0.5)));
    const data = o.getImageData(0, 0, off.width, off.height).data;
    const found: number[] = [];
    for (let y = 0; y < off.height; y++) {
      for (let x = 0; x < off.width; x++) {
        const a = data[(y * off.width + x) * 4 + 3] / 255;
        if (a >= 0.2) found.push(x, y, a);
      }
    }
    return { cols: off.width, rows: off.height, dots: Float32Array.from(found) };
  }, [ready, font, textKey, width, height, pitch, top, lineHeight]);

  // Draw the dots the scan has passed.
  useLayoutEffect(() => {
    const c = canvas.current;
    const ctx = c?.getContext("2d");
    if (c && ctx) {
      ctx.clearRect(0, 0, width, height);
      if (dotSet && resolve < 1) {
        const scanX = trace * (dotSet.cols + 6);
        const { dots } = dotSet;
        for (let i = 0; i < dots.length; i += 3) {
          const x = dots[i];
          const y = dots[i + 1];
          const a = dots[i + 2];
          const behind = scanX - x - (y / dotSet.rows) * 4;
          if (behind < 0) continue;
          const grow = Math.min(1, behind / 6);
          ctx.fillStyle = behind < 2 ? props.accent : alpha(props.color, 0.85);
          ctx.globalAlpha = (1 - resolve) * a;
          ctx.beginPath();
          ctx.arc((x + 0.5) * pitch, (y + 0.5) * pitch, pitch * 0.42 * grow * (0.6 + 0.4 * a), 0, Math.PI * 2);
          ctx.fill();
        }
        // The scan line itself.
        if (trace < 1) {
          ctx.globalAlpha = 0.7 * (1 - resolve);
          ctx.fillStyle = props.accent;
          ctx.fillRect(scanX * pitch, top - fontSize * 0.2, Math.max(2, u * 3), lines.length * lineHeight + fontSize * 0.4);
        }
        ctx.globalAlpha = 1;
      }
    }
    if (ready) releaseFont.current?.();
  });

  return (
    <AbsoluteFill style={{ background: fill(props.background), opacity: out }}>
      <AbsoluteFill
        style={{
          alignItems: "center",
          justifyContent: "center",
          flexDirection: "column",
          opacity: resolve,
          filter: resolve < 1 ? `blur(${((1 - resolve) * 14 * u).toFixed(2)}px)` : undefined,
        }}
      >
        {lines.map((line, i) => (
          <div
            key={i}
            style={{ font, lineHeight: `${lineHeight}px`, color: props.color, textAlign: "center", whiteSpace: "nowrap" }}
          >
            {highlightRuns(line).map((run, j) => (
              <span key={j} style={{ color: run.highlighted ? props.accent : undefined }}>
                {run.text}
              </span>
            ))}
          </div>
        ))}
      </AbsoluteFill>
      <canvas ref={canvas} width={width} height={height} style={{ position: "absolute", inset: 0, width: "100%", height: "100%" }} />
    </AbsoluteFill>
  );
}
